CREATE TABLE public.player_birthdays (user_id uuid PRIMARY KEY, birthday date NOT NULL CHECK (birthday >= DATE '1900-01-01'), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.player_birthdays TO authenticated; GRANT ALL ON public.player_birthdays TO service_role;
ALTER TABLE public.player_birthdays ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Birthday owner or trip captain reads" ON public.player_birthdays FOR SELECT TO authenticated USING (user_id=auth.uid() OR EXISTS (SELECT 1 FROM public.trip_members m JOIN public.trip_members c ON c.trip_id=m.trip_id WHERE m.user_id=player_birthdays.user_id AND c.user_id=auth.uid() AND c.role='captain'));
CREATE POLICY "Owner creates birthday" ON public.player_birthdays FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid());
CREATE POLICY "Owner edits birthday" ON public.player_birthdays FOR UPDATE TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE POLICY "Owner removes birthday" ON public.player_birthdays FOR DELETE TO authenticated USING (user_id=auth.uid());
CREATE TRIGGER player_birthdays_updated BEFORE UPDATE ON public.player_birthdays FOR EACH ROW EXECUTE FUNCTION public.set_trip_updated_at();
CREATE TABLE public.trip_adult_settings (trip_id uuid PRIMARY KEY REFERENCES public.trips(id) ON DELETE CASCADE, enabled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.trip_adult_settings TO authenticated; GRANT ALL ON public.trip_adult_settings TO service_role;
ALTER TABLE public.trip_adult_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Members see adult setting" ON public.trip_adult_settings FOR SELECT TO authenticated USING (trip_private.is_trip_member(trip_id,auth.uid()));
CREATE TRIGGER trip_adult_settings_updated BEFORE UPDATE ON public.trip_adult_settings FOR EACH ROW EXECUTE FUNCTION public.set_trip_updated_at();
CREATE TABLE public.trip_adult_approvals (trip_id uuid NOT NULL REFERENCES public.trips(id) ON DELETE CASCADE, user_id uuid NOT NULL, approved_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(trip_id,user_id));
GRANT SELECT ON public.trip_adult_approvals TO authenticated; GRANT ALL ON public.trip_adult_approvals TO service_role;
ALTER TABLE public.trip_adult_approvals ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner or captain sees approval" ON public.trip_adult_approvals FOR SELECT TO authenticated USING (user_id=auth.uid() OR EXISTS (SELECT 1 FROM public.trip_members m WHERE m.trip_id=trip_adult_approvals.trip_id AND m.user_id=auth.uid() AND m.role='captain'));
CREATE TRIGGER trip_adult_approvals_updated BEFORE UPDATE ON public.trip_adult_approvals FOR EACH ROW EXECUTE FUNCTION public.set_trip_updated_at();
CREATE OR REPLACE FUNCTION trip_private.is_approved_adult(p_trip uuid,p_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $fn$ SELECT EXISTS (SELECT 1 FROM public.trip_adult_settings s JOIN public.trip_adult_approvals a ON a.trip_id=s.trip_id AND a.user_id=p_user JOIN public.player_birthdays b ON b.user_id=p_user WHERE s.trip_id=p_trip AND s.enabled AND b.birthday <= (current_date - interval '21 years')::date AND EXISTS (SELECT 1 FROM public.trip_members m WHERE m.trip_id=p_trip AND m.user_id=p_user)) $fn$;
REVOKE ALL ON FUNCTION trip_private.is_approved_adult(uuid,uuid) FROM PUBLIC;
CREATE OR REPLACE FUNCTION public.set_adult_cards(p_trip uuid,p_enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain') THEN RAISE EXCEPTION 'Captain only'; END IF; INSERT INTO public.trip_adult_settings(trip_id,enabled) VALUES(p_trip,p_enabled) ON CONFLICT(trip_id) DO UPDATE SET enabled=excluded.enabled; END $fn$;
CREATE OR REPLACE FUNCTION public.approve_adult_player(p_trip uuid,p_user uuid,p_approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain') THEN RAISE EXCEPTION 'Captain only'; END IF; IF p_approve THEN IF NOT EXISTS(SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=p_user) OR NOT EXISTS(SELECT 1 FROM public.player_birthdays WHERE user_id=p_user AND birthday <= (current_date - interval '21 years')::date) THEN RAISE EXCEPTION 'Player must be 21 or older'; END IF; INSERT INTO public.trip_adult_approvals(trip_id,user_id,approved_by) VALUES(p_trip,p_user,auth.uid()) ON CONFLICT(trip_id,user_id) DO UPDATE SET approved_by=excluded.approved_by; ELSE DELETE FROM public.trip_adult_approvals WHERE trip_id=p_trip AND user_id=p_user; END IF; END $fn$;
GRANT EXECUTE ON FUNCTION public.set_adult_cards(uuid,boolean),public.approve_adult_player(uuid,uuid,boolean) TO authenticated;
CREATE TABLE public.trip_item_alternatives (trip_id uuid NOT NULL REFERENCES public.trips(id) ON DELETE CASCADE, day_date date NOT NULL, kind text NOT NULL CHECK(kind IN ('bingo','quest','trivia')), item_index integer NOT NULL CHECK(item_index BETWEEN 0 AND 8), user_id uuid NOT NULL, alternative text NOT NULL CHECK(length(alternative) BETWEEN 1 AND 160), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(trip_id,day_date,kind,item_index,user_id));
GRANT SELECT ON public.trip_item_alternatives TO authenticated; GRANT ALL ON public.trip_item_alternatives TO service_role;
ALTER TABLE public.trip_item_alternatives ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Members see group or own swaps" ON public.trip_item_alternatives FOR SELECT TO authenticated USING (trip_private.is_trip_member(trip_id,auth.uid()) AND (user_id=auth.uid() OR user_id=(SELECT m.user_id FROM public.trip_members m WHERE m.trip_id=trip_item_alternatives.trip_id AND m.role='captain' LIMIT 1)));
CREATE TRIGGER trip_item_alternatives_updated BEFORE UPDATE ON public.trip_item_alternatives FOR EACH ROW EXECUTE FUNCTION public.set_trip_updated_at();
CREATE OR REPLACE FUNCTION public.use_item_alternative(p_trip uuid,p_date date,p_kind text,p_index integer,p_alternative text,p_group boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ DECLARE v_captain uuid; v_user uuid; BEGIN IF NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Not a member'; END IF; IF p_date NOT BETWEEN (SELECT start_date FROM public.trips WHERE id=p_trip) AND (SELECT end_date FROM public.trips WHERE id=p_trip) OR p_kind NOT IN ('bingo','quest','trivia') OR p_index NOT BETWEEN 0 AND 8 OR length(trim(p_alternative)) NOT BETWEEN 1 AND 160 THEN RAISE EXCEPTION 'Invalid alternative'; END IF; SELECT user_id INTO v_captain FROM public.trip_members WHERE trip_id=p_trip AND role='captain' LIMIT 1; IF p_group AND NOT (auth.uid()=v_captain OR EXISTS(SELECT 1 FROM public.game_nights WHERE trip_id=p_trip AND host_id=auth.uid() AND starts_at::date=p_date)) THEN RAISE EXCEPTION 'Host or Captain only'; END IF; v_user:=CASE WHEN p_group THEN v_captain ELSE auth.uid() END; INSERT INTO public.trip_item_alternatives(trip_id,day_date,kind,item_index,user_id,alternative) VALUES(p_trip,p_date,p_kind,p_index,v_user,trim(p_alternative)) ON CONFLICT(trip_id,day_date,kind,item_index,user_id) DO UPDATE SET alternative=excluded.alternative; END $fn$;
GRANT EXECUTE ON FUNCTION public.use_item_alternative(uuid,date,text,integer,text,boolean) TO authenticated;
CREATE TABLE public.game_night_turns (trip_id uuid PRIMARY KEY REFERENCES public.trips(id) ON DELETE CASCADE, week_number integer NOT NULL, cards_per_person integer NOT NULL CHECK(cards_per_person BETWEEN 1 AND 5), player_order uuid[] NOT NULL, turn_index integer NOT NULL DEFAULT 0, card_number integer NOT NULL DEFAULT 1, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.game_night_turns TO authenticated; GRANT ALL ON public.game_night_turns TO service_role;
ALTER TABLE public.game_night_turns ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Members see live turns" ON public.game_night_turns FOR SELECT TO authenticated USING (trip_private.is_trip_member(trip_id,auth.uid()));
CREATE TRIGGER game_night_turns_updated BEFORE UPDATE ON public.game_night_turns FOR EACH ROW EXECUTE FUNCTION public.set_trip_updated_at();
CREATE OR REPLACE FUNCTION trip_private.can_run_turns(p_trip uuid,p_week integer) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $fn$ SELECT EXISTS (SELECT 1 FROM public.game_nights n JOIN public.trip_members m ON m.trip_id=n.trip_id AND m.user_id=auth.uid() WHERE n.trip_id=p_trip AND n.week_number=p_week AND (n.host_id=auth.uid() OR m.role IN ('captain','co_captain'))) $fn$;
REVOKE ALL ON FUNCTION trip_private.can_run_turns(uuid,integer) FROM PUBLIC;
CREATE OR REPLACE FUNCTION public.start_game_turns(p_trip uuid,p_week integer,p_cards integer,p_random boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ DECLARE v_order uuid[]; BEGIN IF NOT trip_private.can_run_turns(p_trip,p_week) THEN RAISE EXCEPTION 'Host or leader only'; END IF; IF p_cards NOT BETWEEN 1 AND 5 THEN RAISE EXCEPTION 'Choose 1 to 5 cards'; END IF; SELECT array_agg(user_id ORDER BY CASE WHEN p_random THEN random() ELSE 0 END,joined_at,user_id) INTO v_order FROM public.trip_members WHERE trip_id=p_trip; IF cardinality(v_order)<1 THEN RAISE EXCEPTION 'No players'; END IF; INSERT INTO public.game_night_turns(trip_id,week_number,cards_per_person,player_order,turn_index,card_number,active) VALUES(p_trip,p_week,p_cards,v_order,0,1,true) ON CONFLICT(trip_id) DO UPDATE SET week_number=excluded.week_number,cards_per_person=excluded.cards_per_person,player_order=excluded.player_order,turn_index=0,card_number=1,active=true; END $fn$;
CREATE OR REPLACE FUNCTION public.next_game_turn(p_trip uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ DECLARE v public.game_night_turns; BEGIN SELECT * INTO v FROM public.game_night_turns WHERE trip_id=p_trip FOR UPDATE; IF NOT FOUND OR NOT v.active THEN RAISE EXCEPTION 'No active round'; END IF; IF NOT trip_private.can_run_turns(p_trip,v.week_number) THEN RAISE EXCEPTION 'Host or leader only'; END IF; IF v.turn_index+1 >= cardinality(v.player_order) THEN IF v.card_number>=v.cards_per_person THEN UPDATE public.game_night_turns SET active=false WHERE trip_id=p_trip; ELSE UPDATE public.game_night_turns SET turn_index=0,card_number=card_number+1 WHERE trip_id=p_trip; END IF; ELSE UPDATE public.game_night_turns SET turn_index=turn_index+1 WHERE trip_id=p_trip; END IF; END $fn$;
GRANT EXECUTE ON FUNCTION public.start_game_turns(uuid,integer,integer,boolean),public.next_game_turn(uuid) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.game_night_turns;